#!/usr/bin/env python3
"""Writes the texts the tests of Specs/peer_rules.t27 use, and the secret code's alphabet, from the readable lists below.

The spec carries two generated blocks, each between
    ; >>> generated by Specs/tables/peer_tables.py ...
    ; <<< generated
with named row indexes and the texts as packed UTF-8 bytes with offsets and lengths (t27 has no string
arrays that reach C). The first holds the texts of the first rules; the second (version 2, owner 2026-10-13)
the secret code's alphabet and the texts of the version 2 rules. Run by Specs/generate.sh; edit the lists
here, not the spec. The table layout is ponte_tables.table, so every spec's fixtures read the same way.
"""
import pathlib
import re
import sys

sys.dont_write_bytecode = True
from ponte_tables import arr, table  # noqa: E402  (same folder; generate.sh runs this file directly)

SPECS = pathlib.Path(__file__).resolve().parents[1]
BEGIN = "; >>> generated by Specs/tables/peer_tables.py -- edit the list there, not here"
BEGIN_V2 = "; >>> generated by Specs/tables/peer_tables.py (secret code, version 2 texts) -- edit the lists there, not here"

# What the other Ponte said into the call (its Portuguese TTS) and what this Ponte's recognizer heard.
SIMILARITY_FIXTURES = [
    ("TTS_OI", "Oi, como voce esta?"),
    ("HEARD_OI", "Oi como voce esta"),
    ("TTS_OI_PT", "Oi, como você está?"),
    ("HEARD_OI_PT", "oi como você está"),
    ("TTS_BOM_DIA", "Bom dia, tudo bem com você?"),
    ("HEARD_BOM_DIA", "bom dia tudo bem"),
    ("TTS_THANKS", "Obrigado pela reunião de hoje."),
    ("HEARD_PRICE", "Qual é o preço?"),
    # Cyrillic capitals are not folded (ASCII only): "Privet" and "privet" are different words.
    ("RU_PRIVET", "Привет, как дела?"),
    ("RU_PRIVET_LOWER", "привет как дела"),
    ("SIM_THREE", "sim sim sim nao"),
    ("NAO_TWO", "sim nao nao"),
    ("DIGITS", "Sala 2026, andar 10"),
    ("DIGITS_HEARD", "sala 2026 andar dez"),
    ("PUNCTUATION", "... !? -- ()"),
    ("EMPTY", ""),
]

# Window titles and texts that may carry a Google Meet code; *_CODE: the code the rule returns.
MEET_FIXTURES = [
    ("MEET_TITLE", "Meet - kfs-cgvc-qrk"),
    ("MEET_TITLE_BROWSEROS", "Meet – KFS-CGVC-QRK - BrowserOS"),
    ("MEET_CODE", "kfs-cgvc-qrk"),
    ("MEET_URL", "https://meet.google.com/abc-defg-hij?authuser=0"),
    ("MEET_URL_CODE", "abc-defg-hij"),
    ("MEET_LETTER_BEFORE", "xabc-defg-hij"),
    ("MEET_LETTER_AFTER", "abc-defg-hijk"),
    ("MEET_DIGIT_AFTER", "abc-defg-hij1"),
    ("MEET_SHORT", "ab-cdef-ghi abc-defg-hi abcd-efgh-ijk"),
    ("MEET_TWO", "Meet: xyz-ABCD-efg and abc-defg-hij"),
    ("MEET_TWO_CODE", "xyz-abcd-efg"),
    ("MEET_CYRILLIC", "жabc-defg-hijж"),
    ("MEET_ACCENT", "abc-défg-hij"),
]

# --- Version 2 (owner 2026-10-13) ------------------------------------------------------------------------------
# The secret code shared only among the Russians (secretAlphabet): digits and lowercase ASCII letters without
# 0 1 i l o, which are misread for one another when a code is read out or typed.
SECRET_ALPHABET = "23456789abcdefghjkmnpqrstuvwxyz"

# Containment: what this Ponte's recognizer heard (the phrase) inside what the other Ponte said (its TTS); and
# secret codes as typed or pasted, with what they normalize to and how they are shown.
V2_FIXTURES = [
    ("TTS_CONTRACT", "Entao fica combinado assim: eu preparo tudo hoje a noite e voces podem revisar com calma e, "
                     "se quiserem, assinar o contrato amanha de manha."),
    ("HEARD_TAIL", "o contrato amanha de manha"),
    ("TTS_CONTRACT_PT", "Ent\u00e3o fica combinado assim: eu preparo tudo hoje \u00e0 noite e voc\u00eas podem revisar "
                        "com calma e, se quiserem, assinar o contrato amanh\u00e3 de manh\u00e3."),
    ("HEARD_TAIL_PT", "o contrato amanh\u00e3 de manh\u00e3"),
    ("REPLY", "Sim, podemos comecar agora"),
    ("TTS_QUESTION", "Podemos comecar agora?"),
    ("PHRASE_SEND", "Podemos enviar o contrato amanha"),
    ("TTS_SEND", "Voces podem enviar o contrato hoje?"),
    ("ORDER_SWAPPED", "contrato o"),
    ("ORDER", "o contrato"),
    ("SIM_THREE", "sim sim sim"),
    ("SIM_ONE", "Sim."),
    ("NO_WORDS", "... -- ?!"),
    ("EMPTY", ""),
    ("SECRET_TYPED", "ABCD efgh-JKMN"),
    ("SECRET", "abcdefghjkmn"),
    ("SECRET_DISPLAY", "abcd-efgh-jkmn"),
    ("SECRET_ZERO", "abcd-efgh-jkm0"),
    ("SECRET_UNDERSCORES", "  2345_6789_WXYZ  "),
    ("SECRET_UNDERSCORES_NORMALIZED", "23456789wxyz"),
    ("SECRET_UNDERSCORES_DISPLAY", "2345-6789-wxyz"),
    ("SECRET_SHORT", "abcd-efgh-jkm"),
    ("SECRET_LONG", "abcd-efgh-jkmnp"),
    ("SECRET_WITH_I", "abcd-efgh-ijkm"),
    ("SECRET_TABS", "abcd\tefgh\tjkmn"),
    ("SECRET_ACCENT", "abcd-\u00e9fgh-jkmn"),
    ("SECRET_UPPER", "ABCDEFGHJKMN"),
]


def write_block(spec_name, lines, begin=BEGIN):
    spec = SPECS / spec_name
    source = spec.read_text()
    block = "\n".join([begin] + lines + ["; <<< generated"])
    source, n = re.subn(re.escape(begin) + r".*?; <<< generated", lambda _: block, source, flags=re.S)
    if n != 1:
        sys.exit(f"{spec_name}: generated block not found")
    if any(ord(ch) > 127 for ch in source):
        sys.exit(f"{spec_name}: not ASCII after generation")
    if spec.read_text() != source:
        spec.write_text(source)


def secret_alphabet_lines():
    alphabet = SECRET_ALPHABET
    assert len(alphabet) == 31 and len(set(alphabet)) == len(alphabet), "31 distinct bytes"
    assert list(alphabet) == sorted(alphabet), "sorted, so a reader sees at once what is missing"
    assert all(c in "0123456789abcdefghijklmnopqrstuvwxyz" for c in alphabet), "digits and lowercase ASCII letters"
    assert not set("01ilo") & set(alphabet), "no 0 1 i l o"
    return [f"; The secret code's alphabet: {alphabet}",
            f"pub const PE_SECRET_ALPHABET_LEN : i64 = {len(alphabet)};",
            arr("PE_SECRET_ALPHABET", "u8", list(alphabet.encode("ascii")))]


def main():
    rows = SIMILARITY_FIXTURES + MEET_FIXTURES
    write_block("peer_rules.t27", table("PE_FX", "Texts for the tests", rows, []))
    v2 = secret_alphabet_lines() + table("PE_FX2", "Texts for the tests of the version 2 rules", V2_FIXTURES, [])
    write_block("peer_rules.t27", v2, BEGIN_V2)
    print(f"peer tables: {len(rows) + len(V2_FIXTURES)} fixtures, a secret alphabet of {len(SECRET_ALPHABET)}")


if __name__ == "__main__":
    main()
